    fields = _scan(text)
    result = {
        "days": 0,
        "hours": 0,
        "minutes": 0,
        "seconds": 0,
        "milliseconds": 0,
    }
    for key, value, digit_start, unit_start in fields:
        cap = PARSE_CAP.get(key)
        if cap is not None and value >= cap:
            raise DurationParseError("range", digit_start)
        result[key] = value
    return result


